IF COL_LENGTH(N'dbo.gb_channel', N'status_event') IS NOT NULL EXEC(N' DECLARE @constraint_name sysname; DECLARE @drop_default nvarchar(max); SELECT @constraint_name = dc.name FROM sys.default_constraints dc JOIN sys.columns c ON c.object_id = dc.parent_object_id AND c.column_id = dc.parent_column_id WHERE dc.parent_object_id = OBJECT_ID(N''dbo.gb_channel'') AND c.name = N''status_event''; IF @constraint_name IS NOT NULL BEGIN SET @drop_default = N''ALTER TABLE [dbo].[gb_channel] DROP CONSTRAINT '' + QUOTENAME(@constraint_name); EXEC sys.sp_executesql @drop_default; END; ALTER TABLE [dbo].[gb_channel] DROP COLUMN [status_event]; ');
